import { getStorage, isStorageEnabled } from '.';
import { projectRoot, scopeRoot, userIdFromKey } from './keys';
import type { StorageObject, StorageScope } from './types';

export interface StorageUsage {
	fileCount: number;
	totalBytes: number;
}

export interface UserStorageUsage extends StorageUsage {
	userId: string;
}

/** What one user keeps in one project. */
export const getScopeUsage = async (scope: StorageScope): Promise<StorageUsage> => {
	if (!isStorageEnabled()) {
		return emptyUsage();
	}

	return sumUsage(await getStorage().list(scopeRoot(scope)));
};

/** What every user of a project keeps, heaviest space first. */
export const getProjectUsageByUser = async (projectId: string): Promise<UserStorageUsage[]> => {
	if (!isStorageEnabled()) {
		return [];
	}

	const usageByUser = new Map<string, UserStorageUsage>();

	for (const object of await getStorage().list(projectRoot(projectId))) {
		const userId = userIdFromKey(object.key);
		if (!userId) {
			continue;
		}

		const usage = usageByUser.get(userId) ?? { userId, ...emptyUsage() };
		usage.fileCount += 1;
		usage.totalBytes += object.size;
		usageByUser.set(userId, usage);
	}

	return [...usageByUser.values()].sort((a, b) => b.totalBytes - a.totalBytes);
};

const sumUsage = (objects: StorageObject[]): StorageUsage => {
	return {
		fileCount: objects.length,
		totalBytes: objects.reduce((total, object) => total + object.size, 0),
	};
};

const emptyUsage = (): StorageUsage => ({ fileCount: 0, totalBytes: 0 });

import { env } from '../env';
import * as projectQueries from '../queries/project.queries';
import { getStorageConfig, getStorageHealth, isStorageEnabled } from '../services/storage';
import { getProjectUsageByUser, getScopeUsage } from '../services/storage/usage';
import { adminProtectedProcedure, projectProtectedProcedure } from './trpc';

export const storageRoutes = {
	getConfig: adminProtectedProcedure.query(() => getStorageConfig()),

	getHealth: adminProtectedProcedure.query(async () => {
		const health = await getStorageHealth();
		return { ...health, checkedAt: new Date() };
	}),

	/** What the chat input needs to know before letting someone attach a file. */
	getUploadLimits: projectProtectedProcedure.query(() => ({
		enabled: isStorageEnabled(),
		maxFileSizeMb: env.NAO_STORAGE_MAX_FILE_SIZE_MB,
	})),

	/** Everyone sees their own space; admins also get the breakdown across the project. */
	getUsage: projectProtectedProcedure.query(async ({ ctx }) => {
		const own = await getScopeUsage({ projectId: ctx.project.id, userId: ctx.user.id });

		return {
			own,
			byUser: ctx.userRole === 'admin' ? await getNamedUsageByUser(ctx.project.id) : null,
		};
	}),
};

/** Files outlive membership, so a space whose owner left is labelled by its user id. */
const getNamedUsageByUser = async (projectId: string) => {
	const [usageByUser, members] = await Promise.all([
		getProjectUsageByUser(projectId),
		projectQueries.listUsersWithProjectAccess(projectId),
	]);
	const nameByUserId = new Map(members.map((member) => [member.id, member.name || member.email]));

	return usageByUser.map((usage) => ({ ...usage, name: nameByUserId.get(usage.userId) ?? usage.userId }));
};

import { useQuery } from '@tanstack/react-query';

import { trpc } from '@/main';

export function useStorageConfig({ enabled = true }: { enabled?: boolean } = {}) {
	return useQuery({ ...trpc.storage.getConfig.queryOptions(), enabled });
}

export function useStorageHealth({ enabled = true }: { enabled?: boolean } = {}) {
	return useQuery({ ...trpc.storage.getHealth.queryOptions(), enabled });
}

export function useStorageUploadLimits() {
	return useQuery(trpc.storage.getUploadLimits.queryOptions());
}

export function useStorageUsage({ enabled = true }: { enabled?: boolean } = {}) {
	return useQuery({ ...trpc.storage.getUsage.queryOptions(), enabled });
}

